CREATE OR REPLACE FUNCTION public.admin_users_require_active_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if exists (select 1 from admin_users where role = 'owner' and is_active = true) then
    return null;
  end if;
  raise exception 'at least one active owner admin_users row is required';
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_active_asset_variant_parent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  parent_deleted_at timestamptz;
  parent_purged_at timestamptz;
begin
  select deleted_at, purged_at
    into parent_deleted_at, parent_purged_at
  from public.assets
  where id = new.asset_id and bucket = new.bucket
  for update;

  if not found then
    raise foreign_key_violation using message = 'asset variant parent does not exist in the same bucket';
  end if;
  if parent_deleted_at is not null or parent_purged_at is not null then
    raise check_violation using message = 'asset variants cannot be added to deleted or purged assets';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_revision_no()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.revision_no is null then
      new.revision_no := 1;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.revision_no <= old.revision_no then
      raise exception 'revision_no must be greater than current version';
    end if;
    return new;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.preserve_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
